        uint32_t so=PropOffsetSuper(ClassOf(g_mkComp),"SkeletalMeshAsset"); uint64_t sm=(so!=0xFFFFFFFF&&SafeReadable((void*)(g_mkComp+so),8))?*(uint64_t*)(g_mkComp+so):0;
